def widest_spacing(sites, k):
    s = sorted(sites)

    def fits(gap):
        opened, last = 1, s[0]
        for x in s[1:]:
            if x - last >= gap:
                opened += 1
                last = x
        return opened >= k

    lo, hi = 1, s[-1] - s[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

